const grid = document.getElementById('grid');
const emptyMsg = document.getElementById('empty');
const viewer = document.getElementById('viewer');
const viewerImg = document.getElementById('viewerImg');
const closeViewer = document.getElementById('closeViewer');
const modeButtons = document.querySelectorAll('#modes button');

let photos = [];
let currentIndex = 0;
let cols = 4;

// ---- load photos.json (auto-generated by the GitHub Action) ----
fetch('photos/photos.json?_=' + Date.now())
  .then(r => r.ok ? r.json() : [])
  .catch(() => [])
  .then(list => {
    photos = list || [];
    if (!photos.length) {
      emptyMsg.classList.remove('hidden');
      return;
    }
    renderGrid();
  });

function renderGrid() {
  grid.innerHTML = '';
  photos.forEach((filename, i) => {
    const img = document.createElement('img');
    img.src = 'photos/' + filename;
    img.loading = 'lazy';
    img.addEventListener('click', () => openViewer(i));
    grid.appendChild(img);
  });
  setCols(cols);
}

function setCols(n) {
  cols = Math.max(1, Math.min(10, n));
  grid.style.gridTemplateColumns = `repeat(${cols}, 1fr)`;
}

// ---- mode buttons (preset densities) ----
modeButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    modeButtons.forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    setCols(parseInt(btn.dataset.cols, 10));
  });
});

// ---- pinch gesture on the grid: instead of native zoom, change density ----
let pinchStartDist = null;
let pinchStartCols = 4;

grid.addEventListener('touchstart', (e) => {
  if (e.touches.length === 2) {
    pinchStartDist = touchDistance(e.touches);
    pinchStartCols = cols;
  }
}, { passive: true });

grid.addEventListener('touchmove', (e) => {
  if (e.touches.length === 2 && pinchStartDist) {
    e.preventDefault(); // block native pinch-zoom
    const dist = touchDistance(e.touches);
    const ratio = dist / pinchStartDist;
    // pinch out (ratio > 1) -> fewer columns (bigger photos)
    // pinch in (ratio < 1) -> more columns (denser grid)
    const newCols = Math.round(pinchStartCols / ratio);
    setCols(newCols);
    modeButtons.forEach(b => b.classList.remove('active'));
  }
}, { passive: false });

grid.addEventListener('touchend', (e) => {
  if (e.touches.length < 2) pinchStartDist = null;
});

function touchDistance(touches) {
  const dx = touches[0].clientX - touches[1].clientX;
  const dy = touches[0].clientY - touches[1].clientY;
  return Math.hypot(dx, dy);
}

// ---- fullscreen swipe viewer ----
function openViewer(i) {
  currentIndex = i;
  viewerImg.src = 'photos/' + photos[currentIndex];
  viewer.classList.remove('hidden');
}

function closeViewerFn() {
  viewer.classList.add('hidden');
  viewerImg.src = '';
}

closeViewer.addEventListener('click', closeViewerFn);
viewer.addEventListener('click', (e) => {
  if (e.target === viewer) closeViewerFn();
});

let touchStartX = 0;
let touchStartY = 0;

viewer.addEventListener('touchstart', (e) => {
  if (e.touches.length === 1) {
    touchStartX = e.touches[0].clientX;
    touchStartY = e.touches[0].clientY;
  }
}, { passive: true });

viewer.addEventListener('touchend', (e) => {
  const dx = e.changedTouches[0].clientX - touchStartX;
  const dy = e.changedTouches[0].clientY - touchStartY;
  if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy)) {
    if (dx < 0) showNext(); else showPrev();
  }
}, { passive: true });

function showNext() {
  currentIndex = (currentIndex + 1) % photos.length;
  viewerImg.src = 'photos/' + photos[currentIndex];
}
function showPrev() {
  currentIndex = (currentIndex - 1 + photos.length) % photos.length;
  viewerImg.src = 'photos/' + photos[currentIndex];
}

// arrow keys for desktop testing
document.addEventListener('keydown', (e) => {
  if (viewer.classList.contains('hidden')) return;
  if (e.key === 'ArrowRight') showNext();
  if (e.key === 'ArrowLeft') showPrev();
  if (e.key === 'Escape') closeViewerFn();
});
